// Cache hit : on parse le JSON stocké et on renvoie le contrat
const record = $input.first().json;
const recId = $('Webhook Pourquoi').first().json.params.recId;

let cached;
try {
  cached = JSON.parse(record.response_json);
} catch (e) {
  throw new Error('Cache JSON invalide pour key=' + record.cache_key + '. Détail : ' + e.message);
}

return [{
  json: {
    success: true,
    cached: true,
    generated_at: record.generated_at,
    intervention_id: recId,
    pourquoi: cached.pourquoi
  }
}];

// =====================================================================
// FORMAT PROMPT — Phase 3 W-E3 "Pourquoi causal"
// Construit le payload Anthropic avec tool_use forcé sur submit_pourquoi
// System prompt et tool schema FIGÉS en Phase 2 (bilan Notion 16/05/2026)
// Doctrine Kalystral : "supprimer la friction humaine, pas la déplacer"
// =====================================================================

// --- Récupération des 3 datasets via références cross-node ---
const intervention = $('Search Intervention Cible').first().json;
const machine = $('Search Machine').first().json;
const historiqueRaw = $('Search Historique').all();

// --- Helpers ---
function safe(v, fallback = 'NA') {
  if (v === null || v === undefined || v === '') return fallback;
  return v;
}

function firstFromArray(v) {
  if (Array.isArray(v) && v.length > 0) return v[0];
  return v;
}

function dureeFormat(min) {
  if (!min) return 'NA';
  return min >= 60 ? `${(min / 60).toFixed(1)}h` : `${min}min`;
}

// --- Bloc 1 : INTERVENTION CIBLE ---
const i = intervention;
const machineNomLookup = firstFromArray(i.Machine_nom) || '?';
const agentNomLookup = firstFromArray(i.Agent_nom) || '?';

const interventionBloc = [
  `INTERVENTION CIBLE`,
  `- Date : ${safe(i.Date)}`,
  `- Type : ${safe(i.Type)}`,
  `- Type de panne : ${safe(i.Type_panne)}`,
  `- Statut : ${safe(i.Statut)}`,
  `- Durée : ${dureeFormat(i.Duree_min)}`,
  `- Coût estimé : ${safe(i.Cout_estime, 'NA')} €`,
  `- Machine : ${machineNomLookup}`,
  `- Agent intervenant : ${agentNomLookup}`,
  `- Description : ${safe(i.Description, '(vide)')}`,
  `- Pièces utilisées : ${safe(i['Pièces_utilisées'], '(aucune)')}`,
  `- Remarques rapport : ${safe(i['Remarques_rapport'], '(aucune)')}`,
].join('\n');

// --- Bloc 2 : MACHINE CONTEXTE ---
const m = machine;
const machineBloc = [
  `MACHINE CONTEXTE`,
  `- Nom : ${safe(m.Nom_machine)}`,
  `- Type : ${safe(m.Type)}`,
  `- Localisation : ${safe(m.Localisation)}`,
  `- État actuel : ${safe(m.Etat)}`,
  `- Constructeur : ${safe(m.Constructeur)}`,
  `- N° série : ${safe(m.Num_serie)}`,
  `- Date mise en service : ${safe(m.Date_mise_service)}`,
  `- Dernière maintenance : ${safe(m.Derniere_maintenance)}`,
  `- Prochaine maintenance préventive : ${safe(m.Prochaine_maintenance_Preventive)}`,
  `- Garantie expire : ${safe(m.Garantie_expiration)}`,
].join('\n');

// --- Bloc 3 : HISTORIQUE MACHINE (10 dernières interventions hors cible) ---
const historiqueLines = historiqueRaw.map(item => {
  const h = item.json;
  const desc = (h.Description || '').slice(0, 80).replace(/\n/g, ' ');
  return `- ${safe(h.Date)} | ${safe(h.Type)} | ${safe(h.Type_panne, '-')} | Statut: ${safe(h.Statut, '-')} | ${dureeFormat(h.Duree_min)} | ${desc}`;
}).join('\n');

const historiqueBloc = historiqueRaw.length > 0
  ? `HISTORIQUE MACHINE (${historiqueRaw.length} interventions précédentes, plus récentes en premier)\n${historiqueLines}`
  : `HISTORIQUE MACHINE\n- Aucune intervention précédente sur cette machine`;

// --- Composition user message ---
const userMessage = [
  interventionBloc,
  '',
  machineBloc,
  '',
  historiqueBloc,
  '',
  'Analyse cette intervention en croisant son contenu (description, pièces, remarques) avec le contexte machine et le pattern de l\'historique. Soumets ton verdict via l\'outil submit_pourquoi.'
].join('\n');

// --- System prompt FIGÉ Phase 2 ---
const systemPrompt = `Tu es chef de maintenance dans une PME industrielle de 50 personnes. On t'a transmis une intervention de maintenance ; tu dois en faire l'analyse causale pour ton chef d'atelier. Ton ton est lucide, sobre, factuel. Pas de superlatifs, pas de jargon corporate, pas de blabla. Tu parles vrai, comme un ancien qui a vu passer des pannes.

Tu reçois trois jeux de données : l'intervention cible (date, type, description, pièces, remarques), le contexte machine (localisation, dates clés, garantie), et l'historique des 10 interventions précédentes sur cette même machine.

DOCTRINE NON NÉGOCIABLE — "Supprimer la friction humaine, pas la déplacer" :

- INTERDIT dans le champ action : "organiser une réunion", "aligner l'équipe", "faire un point", "former les agents", "communiquer en interne", "discuter avec X". Aucune action organisationnelle.
- OBLIGATOIRE — cause_probable : s'appuie sur ce qui apparaît dans description, pieces_utilisees ou remarques_rapport, ou dans le pattern de l'historique. Si rien ne pointe une cause précise, formule "cause à investiguer : [hypothèse]" et propose un test ciblé.
- OBLIGATOIRE — action : externe à l'équipe quand c'est possible (contacter le constructeur, commander une pièce chez le fournisseur, faire intervenir un sous-traitant). Si l'action doit être interne, elle est technique et chiffrée (test de pression sous 48h, contrôle du point de fixation Y, remplacement du joint Z), jamais "discuter" ou "faire un point".
- OBLIGATOIRE — delai : chiffré et court ("avant 72h", "sous 7 jours", "avant fin du mois"). Jamais "dès que possible" ou "à planifier".

CAS PRÉVENTIVE : si type === Préventive et qu'aucune anomalie n'est détectable dans description/pièces/remarques, alors verdict = "Intervention préventive standard. Rien à signaler.", fil_temporel reste vide, recommandation = {cause_probable: "NA", action: "NA", delai: "NA"}. Ne force pas un verdict.

TRANSPARENCE : si la cause est incertaine, nuance ("cause probable : X — à confirmer par Y"). Tranche uniquement si 3 indices ou plus convergent (description + pièces + pattern historique par exemple).

VOIX : lucide, sobre, factuelle. Aucune mention "selon les données fournies", "il semble que", "il pourrait être recommandé". Tu tranches.

LANGUE : français.

Tu réponds OBLIGATOIREMENT via l'outil submit_pourquoi, jamais en texte libre.`;

// --- Tool schema FIGÉ Phase 2 ---
const tool = {
  name: 'submit_pourquoi',
  description: 'Soumet l\'analyse causale de l\'intervention',
  input_schema: {
    type: 'object',
    required: ['verdict', 'fil_temporel', 'recommandation'],
    properties: {
      verdict: {
        type: 'string',
        description: '3-4 phrases narratives qui croisent intervention + historique machine + agent. Trace l\'histoire, cite les patterns. Voix lucide, sobre, factuelle.'
      },
      fil_temporel: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            date: { type: 'string', description: 'format JJ/MM' },
            ligne: { type: 'string', description: '1 phrase narrative qui révèle le pattern par répétition lexicale' }
          },
          required: ['date', 'ligne']
        },
        description: '3 à 5 interventions précédentes, reformulées pour faire ressortir la récurrence. Vide si historique trop court ou pas de pattern.'
      },
      recommandation: {
        type: 'object',
        required: ['cause_probable', 'action', 'delai'],
        properties: {
          cause_probable: { type: 'string', description: '1 phrase tranchée pointant une cause technique' },
          action: { type: 'string', description: 'verbe à l\'infinitif, externe à l\'équipe quand possible' },
          delai: { type: 'string', description: 'délai chiffré court' }
        }
      }
    }
  }
};

return [{
  json: {
    anthropic_payload: {
      model: 'claude-haiku-4-5',
      max_tokens: 1500,
      temperature: 0.3,
      system: systemPrompt,
      tools: [tool],
      tool_choice: { type: 'tool', name: 'submit_pourquoi' },
      messages: [
        { role: 'user', content: userMessage }
      ]
    }
  }
}];

// =====================================================================
// FORMAT RESPONSE — Phase 3 W-E3
// Parse la réponse Anthropic tool_use submit_pourquoi
// + filet de sécurité regex si Claude répond en texte libre
// + structure le contrat de sortie + prépare le payload Cache Write
// =====================================================================

const r = $input.first().json;
const recId = $('Webhook Pourquoi').first().json.params.recId;

let pourquoiInput = null;

// --- Cas 1 (nominal) : tool_use forcé ---
if (Array.isArray(r.content)) {
  const toolBlock = r.content.find(b => b.type === 'tool_use' && b.name === 'submit_pourquoi');
  if (toolBlock && toolBlock.input) {
    pourquoiInput = toolBlock.input;
  }
}

// --- Cas 2 (filet de sécurité) : Claude n'a pas utilisé l'outil ---
if (!pourquoiInput && Array.isArray(r.content)) {
  const textBlock = r.content.find(b => b.type === 'text');
  if (textBlock && textBlock.text) {
    try {
      pourquoiInput = JSON.parse(textBlock.text);
    } catch (e) {
      const match = textBlock.text.match(/\{[\s\S]*\}/);
      if (match) {
        try { pourquoiInput = JSON.parse(match[0]); } catch (e2) {}
      }
    }
  }
}

if (!pourquoiInput) {
  throw new Error('Aucun pourquoi exploitable dans la réponse Anthropic. Raw : ' + JSON.stringify(r).slice(0, 500));
}

// --- Normalisation défensive (au cas où Claude omet un champ) ---
const now = new Date().toISOString();
const pourquoi = {
  verdict: pourquoiInput.verdict || '',
  fil_temporel: Array.isArray(pourquoiInput.fil_temporel) ? pourquoiInput.fil_temporel : [],
  recommandation: {
    cause_probable: (pourquoiInput.recommandation && pourquoiInput.recommandation.cause_probable) || 'NA',
    action: (pourquoiInput.recommandation && pourquoiInput.recommandation.action) || 'NA',
    delai: (pourquoiInput.recommandation && pourquoiInput.recommandation.delai) || 'NA'
  }
};

const response = {
  success: true,
  cached: false,
  generated_at: now,
  intervention_id: recId,
  pourquoi: pourquoi
};

return [{
  json: {
    ...response,
    _cache_payload: {
      cache_key: `pourquoi-int-${recId}-v1`,
      endpoint: 'pourquoi',
      response_json: JSON.stringify(response),
      generated_at: now,
      ttl_hours: 720,
      notes: `Auto-généré par workflow Pourquoi pour ${recId}`
    }
  }
}];

// On reprend la réponse construite par Format Response
// et on enlève le _cache_payload avant de répondre au client
const src = $('Format Response').first().json;
const { _cache_payload, ...clean } = src;
return [{ json: clean }];
